 void LoadWave(){editorLoading=true;try{var w=CurrentWave;kindBox.SelectedIndex=w.Kind=="pulse"?0:w.Kind=="command"?1:w.Kind=="tone"?2:3;string[] labels=w.Kind=="pulse"?new[]{L.T("通电时长 μs（1–5000）"),L.T("关闭间隔 μs（0–5000）"),L.T("重复次数（1–100）")}:w.Kind=="command"?new[]{L.T("类型（1 点振 / 2 强点击）"),L.T("强度 dB（-30 至 0）"),""}:new[]{L.T("频率 Hz（40–500）"),L.T("时长 ms（1–80）"),L.T("强度 dB（-30 至 0）")};int[] vals=w.Kind=="pulse"?new[]{w.OnUs,w.OffUs,w.Count}:w.Kind=="command"?new[]{w.Command,w.Gain,0}:new[]{w.Hz,w.Ms,w.Gain};for(int i=0;i<3;i++){waveLabels[i].Text=labels[i];Explain(waveLabels[i],labels[i]);var slider=numberSliders[waveFields[i]];double[] lo=w.Kind=="pulse"?new double[]{1,0,1}:w.Kind=="command"?new double[]{1,-30,0}:new double[]{40,1,-30};double[] hi=w.Kind=="pulse"?new double[]{5000,5000,100}:w.Kind=="command"?new double[]{2,0,1}:new double[]{500,80,0};slider.Minimum=Math.Min(slider.Minimum,lo[i]);slider.Maximum=hi[i];slider.Minimum=lo[i];waveFields[i].Text=vals[i].ToString();waveFields[i].IsEnabled=w.Kind!="none" && !(w.Kind=="command" && i==2);slider.IsEnabled=waveFields[i].IsEnabled;}waveGrid.ColumnDefinitions.Clear();int count=w.Kind=="none"?0:w.Kind=="command"?2:3;for(int i=0;i<count;i++)waveGrid.ColumnDefinitions.Add(new ColumnDefinition());for(int i=0;i<3;i++)((FrameworkElement)waveLabels[i].Parent).Visibility=i<count?Visibility.Visible:Visibility.Collapsed;waveGrid.Visibility=count==0?Visibility.Collapsed:Visibility.Visible;cadenceGrid.Visibility=eventBox.SelectedIndex==0 && w.Kind!="none"?Visibility.Visible:Visibility.Collapsed;waveSummary.Text=L.T("当前：")+w+L.T("\n来源：")+w.Source+" → "+(editedSide==0?L.T("左板"):L.T("右板"))+" / "+(eventBox.SelectedIndex==0?L.T("滑动"):eventBox.SelectedIndex==1?L.T("按压"):L.T("松开"));}finally{editorLoading=false;}}
