 void LoadCandidates(string file){file=CleanRecording(file);if(new FileInfo(file).Length>16*1024*1024)throw new Exception(L.T("录制结果过大。"));var d=new JavaScriptSerializer{MaxJsonLength=16*1024*1024}.DeserializeObject(File.ReadAllText(file)) as Dictionary<string,object>;if(d==null || !d.ContainsKey("candidates"))throw new Exception(L.T("不是录制结果。"));loadedSource=d.ContainsKey("capture_side")?Convert.ToString(d["capture_side"]):"left";candidateBox.Items.Clear();int skipped=0;foreach(var obj in (object[])d["candidates"]){var c=(Dictionary<string,object>)obj;string phase=Convert.ToString(c["phase"]);if(phase!="slow_slide" && phase!="fast_slide" && phase!="press" && phase!="release")continue;try{byte id=Convert.ToByte(Convert.ToString(c["report_id"]).Substring(2),16);string hex=Convert.ToString(c["payload_hex"]);byte[] p=new byte[1+hex.Length/2];p[0]=id;for(int i=1;i<p.Length;i++)p[i]=Convert.ToByte(hex.Substring((i-1)*2,2),16);byte expected=(byte)(id==0x81?(loadedSource=="left"?1:0):(loadedSource=="left"?0:1));if(p[1]!=expected)continue;var wave=WaveSpec.FromPacket(p,(loadedSource=="left"?L.T("Steam 左板"):L.T("Steam 右板"))+" · "+System.IO.Path.GetFileName(System.IO.Path.GetDirectoryName(file)));candidateBox.Items.Add(new Candidate{Wave=wave,Phase=phase,Count=Convert.ToInt32(c["count"]),Text=(phase=="slow_slide"?L.T("慢滑"):phase=="fast_slide"?L.T("快滑"):phase=="press"?L.T("按下"):L.T("松开"))+" · "+wave+" · "+c["count"]+L.T(" 条")});}catch{skipped++;}}if(candidateBox.Items.Count>0){candidateBox.SelectedIndex=0;Directory.CreateDirectory(System.IO.Path.Combine(AppPaths.Data,"profiles"));AtomicWrite(System.IO.Path.Combine(AppPaths.Data,"profiles","last-capture.txt"),System.IO.Path.GetFullPath(file));}recordStatus.Text=candidateBox.Items.Count>0?L.T("录制已载入，可保存为命名配置。"):L.T("未取得可用反馈。");if(candidateBox.Items.Count==0 && d.ContainsKey("message"))recordStatus.Text+="\n"+d["message"];}
 void ApplyCandidate(){var c=candidateBox.SelectedItem as Candidate;if(c==null)throw new Exception(L.T("请先选择录制结果。"));var w=new JavaScriptSerializer().Deserialize<WaveSpec>(new JavaScriptSerializer().Serialize(c.Wave));if(eventBox.SelectedIndex==0)CurrentPad.Motion=w;else if(eventBox.SelectedIndex==1)CurrentPad.PressWave=w;else CurrentPad.ReleaseWave=w;LoadWave();ReadEditor();SavePads();Notice(L.T("已填入当前板、当前事件，可直接微调上方参数。"));}
 void CaptureProgress(){if(recorder!=null && recordResult!=null && File.Exists(recordResult+".progress"))try{recordStatus.Text=File.ReadAllText(recordResult+".progress");}catch(IOException){}}
 async void RecordPad(){if(recorder!=null)return;try{CaptureTool("Python");CaptureTool("Parser");ValidatePresetName(recordName.Text);recordingName=recordName.Text.Trim();recordingSide=editedSide;recordingPreset=full.EditingId;RequireDevice();if(((DeviceChoice)deviceBox.SelectedItem).Pid!=0x1303)throw new Exception(L.T("触觉录制目前仅支持蓝牙连接。"));ReadEditor();SavePads();if(fullTrial)EndFullTrial();Stop();string lab=AppPaths.Capture;Directory.CreateDirectory(System.IO.Path.Combine(AppPaths.Data,"logs"));recordResult=System.IO.Path.Combine(AppPaths.Data,"logs","capture-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+".result");string side=sourceBox.SelectedIndex==0?"left":"right";recorder=Process.Start(new ProcessStartInfo(System.IO.Path.Combine(lab,"SC2CaptureWorker.exe"),"--record "+side+" "+Quote(recordResult)+" "+Quote(selectedDevicePath)){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden});recordButton.IsEnabled=false;stopRecord.IsEnabled=true;recordStatus.Text=L.T("等待管理员提示；录制将按准备、静止、慢滑、快滑、按压进行。");Process active=recorder;await Task.Run(delegate{if(!active.WaitForExit(150000)){File.WriteAllText(recordResult+".stop","stop");throw new Exception(L.T("录制收尾超时，已请求停止，原日志保留。"));}});if(File.Exists(recordResult+".error"))throw new Exception(File.ReadAllText(recordResult+".error"));if(!File.Exists(recordResult))throw new Exception(L.T("录制未产生结果，请查看 logs 文件夹。"));string folder=File.ReadAllText(recordResult).Trim();string python=CaptureTool("Python");recordStatus.Text=L.T("正在解析完整触觉报文…");await Task.Run(delegate{using(var p=Process.Start(new ProcessStartInfo(python,Quote(System.IO.Path.Combine(lab,"auto_capture.py"))+" "+Quote(folder)+" --parser "+Quote(CaptureTool("Parser"))){UseShellExecute=false,CreateNoWindow=true})){if(!p.WaitForExit(120000)){p.Kill();throw new Exception(L.T("分析超时。"));}if(p.ExitCode!=0)throw new Exception(L.T("分析失败，原日志保留。"));}});LoadCandidates(System.IO.Path.Combine(folder,"haptics.json"));CreateRecordedPreset();}catch(Exception e){recordStatus.Text=L.T("录制停止：")+e.Message;}finally{if(recorder!=null){recorder.Dispose();recorder=null;}recordButton.IsEnabled=true;stopRecord.IsEnabled=false;}}
 void StartPadTrial(){StartFullTrial();}
 void UpdateMotionFields(){if(inertiaBox==null)return;bool mouse=actionBox.SelectedIndex==0,scroll=actionBox.SelectedIndex==1;foreach(string k in new[]{"speed","smooth"})parameterCells[k].Visibility=mouse?Visibility.Visible:Visibility.Collapsed;parameterCells["scroll"].Visibility=scroll?Visibility.Visible:Visibility.Collapsed;parameterCells["reversal"].Visibility=scroll?Visibility.Visible:Visibility.Collapsed;if(scrollDirection!=null){scrollDirectionHost.Visibility=scroll?Visibility.Visible:Visibility.Collapsed;}inertiaBox.Visibility=mouse?Visibility.Visible:Visibility.Collapsed;parameterCells["friction"].Visibility=mouse && inertiaBox.IsChecked==true?Visibility.Visible:Visibility.Collapsed;var visible=new List<FrameworkElement>();foreach(string key in new[]{"speed","smooth","scroll","reversal","press","release","friction"})if(parameterCells[key].Visibility==Visibility.Visible)visible.Add(parameterCells[key]);int columns=Math.Min(3,visible.Count);motionGrid.ColumnDefinitions.Clear();motionGrid.RowDefinitions.Clear();for(int c=0;c<columns;c++)motionGrid.ColumnDefinitions.Add(new ColumnDefinition());for(int r=0;r<(visible.Count+columns-1)/columns;r++)motionGrid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});for(int i=0;i<visible.Count;i++){Grid.SetColumn(visible[i],i%columns);Grid.SetRow(visible[i],i/columns);}}
 string CleanRecording(string file){string lab=AppPaths.Capture;if(System.IO.Path.GetFileName(file)=="haptics.cleaned.json")file=System.IO.Path.Combine(System.IO.Path.GetDirectoryName(file),"haptics.json");string python=CaptureTool("Python");using(var p=Process.Start(new ProcessStartInfo(python,"-X utf8 "+Quote(System.IO.Path.Combine(lab,"clean_capture.py"))+" "+Quote(file)){UseShellExecute=false,CreateNoWindow=true})){if(!p.WaitForExit(10000)){p.Kill();throw new Exception(L.T("录制筛选超时，原文件保留。"));}if(p.ExitCode!=0)throw new Exception(L.T("无法校验录制动作，未应用此结果；需要原始输入记录。"));}return System.IO.Path.Combine(System.IO.Path.GetDirectoryName(file),"haptics.cleaned.json");}
 bool liveBridge;
